 Embedded for offline reading. SVG ornament and layout authored for this template.
 Change typography and palette here; artwork is bound only to its own elements. */
:root {
 color-scheme:light;
 --hd-paper-wash:rgba(243,233,213,.64);
 --reader-text-color:#2e211b; --reader-page-background:#f3e9d5; --reader-accent:#8f382e;
 --reader-font-family:Georgia,"Noto Serif",serif; --reader-font-size:19px;
 --reader-line-height:1.85; --reader-paragraph-indent:1.5em; --reader-paragraph-spacing:.6em;
 --hd-heading:#48201a; --hd-muted:#3c2b1f; --hd-gold:#a17d46; --hd-rule:#cbb798;
 --hd-seal:#913d32; --hd-lantern-ink:#b08c50; --hd-art-filter:saturate(.85); --hd-jade-filter:none;
}
.reader-template-page {padding:0;}
body {color:var(--reader-text-color);background:var(--reader-page-background);font:400 var(--reader-font-size)/var(--reader-line-height) var(--reader-font-family);letter-spacing:normal;text-align:justify;}
.hd-page,.hd-page *,.hd-page *::before,.hd-page *::after {box-sizing:border-box;}
.hd-page {position:relative;isolation:isolate;--hd-top-height:clamp(68px,10vh,90px);width:100%;height:100%;min-width:0;min-height:0;display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;gap:9px;background:var(--reader-page-background);padding:calc(13px + var(--reader-safe-top,0px)) calc(20px + var(--reader-safe-right,0px)) calc(9px + var(--reader-safe-bottom,0px)) calc(20px + var(--reader-safe-left,0px));}
.hd-hero {height:var(--hd-top-height);position:relative;isolation:isolate;overflow:hidden;background:transparent;color:#f0d8a4;}
.hd-hero-frame::before,.hd-hero-frame::after {content:"";position:absolute;width:13px;height:13px;border:1px solid #c09a60;}
.hd-hero-copy {position:absolute;left:20px;right:48px;top:50%;transform:translateY(-50%);text-align:left;}
.hd-eyebrow {display:flex;align-items:center;gap:6px;font:8px/1.4 sans-serif;letter-spacing:.16em;color:#d9b47c;}
.hd-hairline {width:16px;height:1px;background:currentColor;flex-shrink:0;}
.hd-hero-copy strong {display:block;margin:7px 0 5px;font-size:clamp(23px,6.2vw,33px);font-weight:400;line-height:1.25;letter-spacing:-.03em;text-shadow:0 2px 9px #251310;}
.hd-hero-sub {font-size:10px;font-style:italic;line-height:1.5;color:#d9bfa0;}
.hd-seal {position:absolute;right:17px;top:17px;padding:4px 3px;border:1px solid #cf9e70;outline:1px solid #b77a57;outline-offset:2px;background:#74332b;color:#e2b88b;font:11px/1.25 serif;text-align:center;}
.hd-hero-cloud {position:absolute;right:15px;bottom:14px;color:#c6a56b;opacity:.6;width:60px;height:18px;}
.hd-hero-cloud svg {display:block;width:100%;height:100%;}
.hd-bookline {display:flex;align-items:center;gap:8px;min-width:0;height:23px;color:var(--hd-muted);font:10px/1.4 sans-serif;letter-spacing:.04em;}
.hd-bookline>[data-reader-field] {overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.hd-diamond {width:5px;height:5px;transform:rotate(45deg);border:1px solid var(--hd-gold);flex-shrink:0;}
.hd-book-label {flex-shrink:0;margin-left:auto;font-size:8px;letter-spacing:.12em;color:var(--hd-heading);}
.hd-paper {position:relative;display:grid;grid-template-rows:minmax(0,1fr);min-width:0;min-height:0;border-top:1px solid var(--hd-rule);padding-top:13px;}
.hd-paper::before {content:"";position:absolute;left:0;top:-1px;width:28px;border-top:2px solid var(--hd-heading);pointer-events:none;}
.hd-flow {min-width:0;min-height:0;}
.hd-page .reader-chapter-title {margin:0 0 .7em;font-size:1.35em;font-weight:500;line-height:1.5;text-align:left;color:var(--hd-heading);overflow-wrap:anywhere;break-inside:auto;}
.hd-page .reader-paragraph {margin:0 0 var(--reader-paragraph-spacing);text-indent:var(--reader-paragraph-indent);orphans:1;widows:1;}
.hd-page .reader-paragraph[data-split-from],.hd-page [data-reader-continuation] {text-indent:0;}
.hd-page pre {white-space:pre-wrap;overflow-wrap:anywhere;orphans:1;widows:1;}
.hd-page figure {margin:0 0 .6em;max-width:100%;}
.hd-running {display:flex;align-items:center;gap:10px;min-width:0;height:var(--hd-top-height);color:#e3c9a4;font:9px/1.4 sans-serif;}
.hd-running-brand {display:flex;align-items:center;gap:7px;flex-shrink:0;color:#e0bc82;letter-spacing:.12em;}
.hd-running-brand svg {display:block;width:20px;height:29px;color:var(--hd-lantern-ink);}
.hd-running-book {overflow:hidden;white-space:nowrap;text-overflow:ellipsis;margin-left:auto;text-align:right;}
.hd-small-seal {flex-shrink:0;border:1px solid #d5ad77;padding:1px 3px;color:#e0bc82;font:11px/1.2 serif;}
.hd-chapterline {display:flex;align-items:center;justify-content:center;gap:10px;min-width:0;height:23px;color:var(--hd-muted);font:11px/1.4 var(--reader-font-family);}
.hd-chapterline span {overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.hd-chapterline i {flex-shrink:0;width:18px;height:5px;border-top:1px solid var(--hd-rule);border-bottom:1px solid var(--hd-rule);}
.hd-footer {min-height:34px;display:flex;align-items:center;justify-content:space-between;gap:10px;min-width:0;border-top:1px solid var(--hd-rule);padding-top:7px;color:#e0c5a0;font:10px/1.4 sans-serif;font-variant-numeric:tabular-nums;}
.hd-foot-side,.hd-progress {flex:1 1 0;min-width:0;white-space:nowrap;}
.hd-foot-label {display:none;}
.hd-progress {text-align:right;}
.hd-folio {display:flex;align-items:center;gap:8px;flex-shrink:0;white-space:nowrap;color:#eed2a6;}
.hd-jade {display:block;width:20px;height:20px;flex-shrink:0;border-radius:50%;border:1px solid var(--hd-gold);background-size:300%;background-position:50% 55%;filter:var(--hd-jade-filter);}
.hd-page [aria-hidden="true"] {pointer-events:none;user-select:none;}
@media(min-width:600px) {.hd-foot-label {display:inline;margin-left:12px;font-size:8px;letter-spacing:.12em;}}
@media(max-width:350px) {.hd-page {padding-left:calc(13px + var(--reader-safe-left,0px));padding-right:calc(13px + var(--reader-safe-right,0px));}.hd-hero-copy {left:16px;right:42px;}.hd-hero-copy strong {font-size:23px;}.hd-hero-sub {font-size:9px;}.hd-running-brand span {display:none;}.hd-book-label {font-size:7px;}}
@media(max-height:560px) {.hd-page {gap:5px;padding-top:calc(8px + var(--reader-safe-top,0px));padding-bottom:calc(6px + var(--reader-safe-bottom,0px));}.hd-page {--hd-top-height:58px;}.hd-hero-copy strong {font-size:24px;margin:3px 0;}.hd-hero-sub,.hd-hero-cloud {display:none;}.hd-eyebrow {font-size:7px;}.hd-seal {top:13px;font-size:9px;}.hd-bookline,.hd-chapterline {height:18px;}.hd-continuation {--hd-top-height:44px;}.hd-running-brand svg {height:24px;}.hd-paper {padding-top:7px;}.hd-footer {padding-top:5px;min-height:27px;}.hd-jade {width:15px;height:15px;}}
@media(max-height:360px) {.hd-page {--hd-top-height:44px;}.hd-eyebrow,.hd-seal {display:none;}.hd-hero-copy strong {font-size:22px;}.hd-bookline {height:15px;}.hd-page {gap:4px;}}
@media(prefers-color-scheme:dark) {
 :root:not([data-reader-color-scheme="light"]) {color-scheme:dark;--hd-paper-wash:rgba(33,27,25,.50);--reader-text-color:#f0e1c9;--reader-page-background:#211b19;--reader-accent:#d8a171;
 --hd-heading:#f6dfbf;--hd-muted:#efdfc8;--hd-gold:#a48254;--hd-rule:#574239;
 --hd-seal:#713329;--hd-lantern-ink:#c6a06a;--hd-art-filter:brightness(.65) saturate(.8);--hd-jade-filter:brightness(.8);}
}
:root[data-reader-color-scheme="dark"] {color-scheme:dark;--hd-paper-wash:rgba(33,27,25,.50);--reader-text-color:#f0e1c9;--reader-page-background:#211b19;--reader-accent:#d8a171;
 --hd-heading:#f6dfbf;--hd-muted:#efdfc8;--hd-gold:#a48254;--hd-rule:#574239;
 --hd-seal:#713329;--hd-lantern-ink:#c6a06a;--hd-art-filter:brightness(.65) saturate(.8);--hd-jade-filter:brightness(.8);}


.hd-jade {background-image:url("data:image/jpeg;base64,");}


.hd-continuation {--hd-top-height:clamp(44px,7vh,60px);}
.hd-backdrop,.hd-page-veil {position:absolute;inset:0;pointer-events:none;z-index:-2;}
.hd-backdrop {background-size:cover;background-position:center 62%;filter:var(--hd-art-filter);}
.hd-page-veil {z-index:-1;background:linear-gradient(to bottom,rgba(25,13,12,.22) 0px,rgba(25,13,12,.12) calc(var(--reader-safe-top,0px) + var(--hd-top-height) - 12px),var(--hd-paper-wash) calc(var(--reader-safe-top,0px) + var(--hd-top-height) + 48px),var(--hd-paper-wash) calc(100% - var(--reader-safe-bottom,0px) - 46px),rgba(25,13,12,.3) calc(100% - var(--reader-safe-bottom,0px) - 12px),rgba(25,13,12,.32) 100%);}
.hd-running {text-shadow:0 1px 5px #20100d;}
.hd-footer {border-top:0;text-shadow:0 1px 4px #281914;}
@media(max-height:560px) {.hd-continuation {--hd-top-height:44px;}.hd-page-veil {background:linear-gradient(to bottom,rgba(25,13,12,.22),var(--hd-paper-wash) calc(var(--reader-safe-top,0px) + var(--hd-top-height) + 35px),var(--hd-paper-wash) calc(100% - var(--reader-safe-bottom,0px) - 36px),rgba(25,13,12,.3) 100%);}}

.hd-backdrop {background-image:url("data:image/jpeg;base64,");}
